    class Histogram:
        def __init__(self):
            self.data = []
        def get_max_value(self):
            return max(self.data) if self.data else 0

    class LatencyStats:
        def __init__(self):
            self.values = []
        def record_latency(self, latency):
            self.values.append(latency)
        def get_interval_histogram(self):
            h = Histogram()
            h.data = list(self.values)
            return h

